class ClothingItem {\n  final String id;\n  final String imagePath;\n  final String category; // Shirt, Pants, Shoes, etc.\n  final String color;\n  final String? size;\n  final String? brand;\n  final DateTime uploadedAt;\n  final bool isFavorite;\n\n  ClothingItem({\n    required this.id,\n    required this.imagePath,\n    required this.category,\n    required this.color,\n    this.size,\n    this.brand,\n    required this.uploadedAt,\n    this.isFavorite = false,\n  });\n}\n\nclass Outfit {\n  final String id;\n  final String eventType; // Casual, Formal, Party, etc.\n  final List<ClothingItem> items;\n  final String? occasionDetails;\n  final DateTime createdAt;\n  final double? stylScore;\n\n  Outfit({\n    required this.id,\n    required this.eventType,\n    required this.items,\n    this.occasionDetails,\n    required this.createdAt,\n    this.stylScore,\n  });\n}\n\nclass BeautyRecommendation {\n  final String id;\n  final String category; // Makeup, Hairstyle\n  final String type;\n  final String description;\n  final String? imageUrl;\n  final List<String> products;\n  final double compatibility; // 0.0 - 1.0\n\n  BeautyRecommendation({\n    required this.id,\n    required this.category,\n    required this.type,\n    required this.description,\n    this.imageUrl,\n    required this.products,\n    required this.compatibility,\n  });\n}\n